<?php
require_once dirname(__DIR__) . '/vendor/autoload.php';
use PHPMailer\PHPMailer\PHPMailer;
function sendVerificationOtp($email,$name,$otp){$mail=new PHPMailer(true);$mail->isSMTP();$mail->Host=$_ENV['SMTP_HOST'];$mail->SMTPAuth=true;$mail->Username=$_ENV['SMTP_USERNAME'];$mail->Password=$_ENV['SMTP_PASSWORD'];$mail->SMTPSecure=$_ENV['SMTP_ENCRYPTION']==='tls'?PHPMailer::ENCRYPTION_STARTTLS:PHPMailer::ENCRYPTION_SMTPS;$mail->Port=(int)$_ENV['SMTP_PORT'];$mail->setFrom($_ENV['SMTP_FROM_ADDRESS'],$_ENV['SMTP_FROM_NAME']);$mail->addAddress($email,$name);$mail->isHTML(true);$mail->Subject='Verify your email - UniCanteen';$mail->Body='<h2>Verify your email</h2><p>Your UniCanteen verification code is:</p><h1 style="letter-spacing:6px">'.$otp.'</h1><p>This code expires in 5 minutes. Do not share it with anyone.</p>';$mail->AltBody="Your UniCanteen verification code is $otp. It expires in 5 minutes.";$mail->send();}
function sendPasswordResetOtp($email,$name,$otp){$mail=new PHPMailer(true);$mail->isSMTP();$mail->Host=$_ENV['SMTP_HOST'];$mail->SMTPAuth=true;$mail->Username=$_ENV['SMTP_USERNAME'];$mail->Password=$_ENV['SMTP_PASSWORD'];$mail->SMTPSecure=$_ENV['SMTP_ENCRYPTION']==='tls'?PHPMailer::ENCRYPTION_STARTTLS:PHPMailer::ENCRYPTION_SMTPS;$mail->Port=(int)$_ENV['SMTP_PORT'];$mail->setFrom($_ENV['SMTP_FROM_ADDRESS'],$_ENV['SMTP_FROM_NAME']);$mail->addAddress($email,$name);$mail->isHTML(true);$mail->Subject='Reset your password - UniCanteen';$mail->Body='<h2>Reset your password</h2><p>Your UniCanteen reset code is:</p><h1 style="letter-spacing:6px">'.$otp.'</h1><p>This code expires in 5 minutes. Do not share it with anyone.</p>';$mail->AltBody="Your UniCanteen reset code is $otp. It expires in 5 minutes.";$mail->send();}
